from lms_communication.ws import main as ws_main
import asyncio
from lms_harmony.handlers.get_stop_tokens import GetStopTokensHandler
from lms_harmony.handlers.render_chat_to_text import RenderChatToTextHandler
import lms_harmony.model as model

namespace = "OpenaiInputOutputPreprocessing"
endpoint_handlers = {
    "GetStopTokens": GetStopTokensHandler,
    "RenderChatToText": RenderChatToTextHandler,
}
asyncio.run(
    ws_main(
        namespace=namespace,
        endpoint_handlers=endpoint_handlers,
        model_module=model,
    )
)
